CREATE TABLE public.advisor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role text NOT NULL CHECK (role IN ('user','assistant')), content text NOT NULL CHECK (length(content) BETWEEN 1 AND 24000), request_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, request_id, role)); GRANT SELECT, INSERT ON public.advisor_messages TO authenticated; GRANT ALL ON public.advisor_messages TO service_role; ALTER TABLE public.advisor_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own advisor messages" ON public.advisor_messages FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE INDEX advisor_messages_user_time ON public.advisor_messages(user_id, created_at);